import React, { useEffect, useState } from 'react';
import { Box, IconButton } from '@mui/material';
import CloseIcon from '@mui/icons-material/Close';
import { Link as RouterLink, useLocation } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import MoonCanvas from '../../features/ramadan/MoonCanvas';
import { inSeason, moonPhase, pad2, useRamadanCountdown, FIRST_NIGHT } from '../../features/ramadan/ramadanSeason';

// A slim band above the header on every page until Eid: the moon, the count to
// Ramadan, and a way to be reminded. A visitor can close it; it stays closed for them.
const KEY = 'ramadan-bar-1448';
const C = { night: '#060A1F', gold: '#E8C46A', goldHi: '#FFF0C2', mist: '#A9B0CC' };

export default function RamadanBar() {
    const { t } = useTranslation();
    const { pathname } = useLocation();
    const count = useRamadanCountdown();
    const [closed, setClosed] = useState(true);

    useEffect(() => {
        try { setClosed(window.localStorage.getItem(KEY) === '1'); } catch (e) { setClosed(false); }
    }, []);

    if (closed || !count || !inSeason(count.now) || pathname.replace(/\/$/, '') === '/ramadan') return null;
    const close = () => {
        setClosed(true);
        try { window.localStorage.setItem(KEY, '1'); } catch (e) { /* storage blocked: closed for this visit */ }
    };
    const day = Math.floor((count.now - FIRST_NIGHT().getTime()) / 864e5) + 1;

    return (
        <Box component="aside" aria-label={t('ramadanBar.label')} sx={{
            position: 'relative', zIndex: 2, color: '#F4ECDC',
            background: `radial-gradient(60% 220% at 50% 0%, rgba(232,196,106,.16), transparent 70%), ${C.night}`,
            borderBottom: '1px solid rgba(232,196,106,.25)',
        }}>
            <Box sx={{
                maxWidth: 1200, mx: 'auto', minHeight: 48, display: 'flex', alignItems: 'center', justifyContent: 'center',
                gap: { xs: 1.2, sm: 2 }, pl: 'max(16px, env(safe-area-inset-left, 0px))', pr: 'max(48px, env(safe-area-inset-right, 0px))', py: 0.75, flexWrap: 'wrap',
            }}>
                <Box sx={{ width: 22, flexShrink: 0 }}><MoonCanvas phase={moonPhase(count.now)} halo={false} label="" /></Box>
                {count.begun ? (
                    <Box component="span" sx={{ fontSize: 14 }}>{t('ramadanBar.mubarak', { day })}</Box>
                ) : (
                    <Box component="span" sx={{ fontSize: 14, display: 'inline-flex', gap: 1, alignItems: 'baseline', flexWrap: 'wrap', justifyContent: 'center' }}>
                        <span>{t('ramadanBar.in', { n: count.days })}</span>
                        <Box component="span" aria-hidden sx={{ fontFamily: '"Marcellus", Georgia, serif', color: C.goldHi, fontVariantNumeric: 'tabular-nums', letterSpacing: '.04em', display: { xs: 'none', sm: 'inline' } }}>
                            {pad2(count.hours)}:{pad2(count.minutes)}:{pad2(count.seconds)}
                        </Box>
                    </Box>
                )}
                <Box component={RouterLink} to={count.begun ? '/ramadan/' : '/ramadan/#remind'} sx={{
                    minHeight: 32, px: 1.6, display: 'inline-flex', alignItems: 'center', borderRadius: 99, fontSize: 13, fontWeight: 600,
                    color: C.night, bgcolor: C.gold, textDecoration: 'none', '&:hover': { bgcolor: C.goldHi },
                    '&:focus-visible': { outline: `2px solid ${C.goldHi}`, outlineOffset: 2 },
                }}>
                    {count.begun ? t('ramadanBar.open') : t('ramadanBar.remind')}
                </Box>
            </Box>
            <IconButton onClick={close} aria-label={t('ramadanBar.close')} size="small" sx={{
                position: 'absolute', top: '50%', transform: 'translateY(-50%)', insetInlineEnd: 'max(6px, env(safe-area-inset-right, 0px))', color: C.mist, width: 40, height: 40,
            }}>
                <CloseIcon fontSize="small" />
            </IconButton>
        </Box>
    );
}
